import{_ as t,o as l,c as i,j as e,a,a5 as o}from"./chunks/framework.R-FQ1xZ2.js";const f=JSON.parse('{"title":"MCP 三层架构","description":"Host / Client / Server 三层，以及 Tools、Resources、Prompts 三类原语各管什么。","frontmatter":{"title":"MCP 三层架构","description":"Host / Client / Server 三层，以及 Tools、Resources、Prompts 三类原语各管什么。"},"headers":[],"relativePath":"diagrams/mcp-architecture.md","filePath":"diagrams/mcp-architecture.md","lastUpdated":null}'),s={name:"diagrams/mcp-architecture.md"};function c(n,r,d,u,h,m){return l(),i("div",null,[...r[0]||(r[0]=[e("h1",{id:"mcp-三层架构",tabindex:"-1"},[a("MCP 三层架构 "),e("a",{class:"header-anchor",href:"#mcp-三层架构","aria-label":'Permalink to "MCP 三层架构"'},"​")],-1),e("p",null,[e("span",{class:"fig-badge"},"架构图"),a(),e("code",null,"architecture")],-1),e("blockquote",null,[e("p",null,[e("strong",null,"一句话"),a("：Host / Client / Server 三层，以及 Tools、Resources、Prompts 三类原语各管什么。")])],-1),e("div",{class:"fig-frame"},[e("iframe",{src:"/fig/mcp-architecture.html",title:"MCP 三层架构",loading:"lazy",allowfullscreen:""})],-1),o('<p class="fig-actions"><a href="/fig/mcp-architecture.html" target="_blank" rel="noreferrer">在新窗口打开（可缩放 / 切换明暗主题 / 导出图片）</a></p><h2 id="怎么读这张图" tabindex="-1">怎么读这张图 <a class="header-anchor" href="#怎么读这张图" aria-label="Permalink to &quot;怎么读这张图&quot;">​</a></h2><ol><li>Host 是宿主应用（比如你的 IDE 或 Agent 运行时），它内部为每个 Server 起一个 Client。</li><li>Server 通过 stdio 或 HTTP 暴露能力，协议本身是 JSON-RPC 2.0。</li><li>三类原语的分工：Tools 是模型能主动调用的动作；Resources 是应用决定加载的只读数据；Prompts 是用户显式选择的模板。</li><li>关键设计意图是<strong>解耦</strong>——工具实现不再和 Agent 应用编译在一起，可以跨进程、跨语言、跨机器。</li></ol><h2 id="面试口径" tabindex="-1">面试口径 <a class="header-anchor" href="#面试口径" aria-label="Permalink to &quot;面试口径&quot;">​</a></h2><ul><li>「MCP 解决了什么痛点？」——N 个模型 × M 个工具原本要 N×M 套集成，MCP 把它压成 N+M。</li><li>「MCP 和直接写 @tool 有什么区别？」——进程边界与生命周期归谁管、能力怎么被发现、授权怎么做。代价是多了一层协议开销和部署复杂度。</li><li>「Server 崩溃了你的 Agent 会怎样？」——要能说出连接保活、超时、重连与降级策略。</li></ul><h2 id="相关笔记" tabindex="-1">相关笔记 <a class="header-anchor" href="#相关笔记" aria-label="Permalink to &quot;相关笔记&quot;">​</a></h2><ul><li><a href="/learn/kb/l4-agent/">L4 Agent 与工具生态</a></li><li><a href="/learn/diagrams/function-calling-flow.html">Function Calling 消息往返</a></li></ul>',7)])])}const g=t(s,[["render",c]]);export{f as __pageData,g as default};
